#define PALM_V28DR_ROUTE_GENERIC_PASS 10L
#define PALM_V28DR_ROUTE_SHORT_REPLAY 11L

/* v28DS: only otherwise eligible SHORT-REPLAY candidates consult M40. */
#define PALM_V28DS_SHORT_REPLAY_M40_MAX 3L
/* v28DZ: recover only fully buffered short two-finger episodes that stayed
 * inside a strict raw two-contact ceiling. A minimum of three clean two-contact
 * frames is required, and the recovery window ends at 55 ms. */
#define PALM_V28DZ_SHORT_TWO_REPLAY_MAX_DURATION_US 55000LL
#define PALM_V28DZ_SHORT_TWO_MIN_FRAMES 3L

/* v28EK: narrow END-only grace for a fully buffered clean 2F tap.
 * IMPORTANT: the global v28DZ 55ms ceiling is intentionally unchanged.
 * Only END replay may use the extra 55..60ms branch after all existing
 * v28DZ safety gates and the additional v28EK structural gates pass.
 */
#define PALM_V28EK_SHORT_TWO_END_GRACE_MAX_DURATION_US 60000LL
#define PALM_V28EK_SHORT_TWO_END_GRACE_MIN_FRAMES 6L
#define PALM_V28EK_SHORT_TWO_END_GRACE_MIN_CLEAN_FRAMES 6L
#define PALM_V28EK_SHORT_TWO_END_GRACE_FIRST_TWO_MAX_US 15000LL
#define PALM_V28EK_SHORT_TWO_END_GRACE_MIN_PAIR_DISTANCE_SQUARED 640000ULL

