    /* 0.1.25: floor wait, track end, two lost - see PALM_V0125_FIRST_PASS_MIN_US. */
    LONG v0125FastFloorWait;
    LONG v0125FastBrokeToLog;
    LONG v0125FloorTwoLostToLog;
    /* 1.0.1-exp: V101X SIZE3-ALL-HOLD - see g_V101XSize3Holds. */
    LONG v101xSize3All;
    LONG v101xFastSize3Wait;
    LONG v101xHoldToLog;
    LONG v101xMax;
    LONG v101xGe3;
    LONG v101xLive;
    LONGLONG v101xSizeAgeUs;
    LONGLONG v101xLogClassUs;
    LONGLONG v101xLogWindowUs;
    PCSTR v101xLogMode;
    LONG v101xLogPrimaryHold;
    /* 0.1.17: primary hold, first-pass branch, handoff - see below. */
    LONG v0117PrimaryHold;
