    LONG v0117MicroStalePen;
    LONGLONG v0117MicroBufferUs;
    LONGLONG v0117PrimaryAgeUs;
    LONGLONG v0117EpisodeUs;
    LONGLONG v0117ClassUs;
    LONGLONG v0117HandoffSessionAgeUs;
    LONGLONG v0117HandoffExitAgeUs;
    /* 0.1.27: V0127 PALM-ID-HOLD - see g_V0127PalmIdMask. */
    LONG v0127HoldToLog;
    LONG v0127Route;
    LONG v0127Ids;
    LONG v0127MoveMax;
    LONGLONG v0127MarkAgeUs;
    LONGLONG v0127ClassUs;
    LONG bpPreGateEndToLog;
    PCSTR bpPreGateEndReason;
    LONG bqQuickRestartBlockToLog;
    LONG bqPalmLatchStartToLog;
    LONG bqPalmLatchHitToLog;
    LONG bqPalmLatchEndToLog;
    PCSTR bqPalmLatchStartReason;
    LONG bsPalmSessionStartToLog;
    LONG bsPalmSessionHitToLog;
    LONG bsPalmSessionEndToLog;
    PCSTR bsPalmSessionStartReason;
    PCSTR bsPalmSessionEndReason;
    PCSTR shadowReason;
    LONGLONG shadowElapsed100ns;
    LONGLONG shadowElapsedUs;
    LONGLONG v0116FastElapsedUs;
