    /*
     * 0.1.27: the first frame of a class the V0127 PALM-ID-HOLD took back.
     * size is the largest contact size of the newest vendor report (A486) and
     * sizeAgeUs its age; moveMax the largest x or y travel, in wire units, of
     * a held contact since its mark.  They are for reading each hold by hand:
     * a finger that outlived a hand should read size 1-2 and travel, and
     * most hand remains read 3+ and sit still - but not all (0.1.12 real use
     * 2, 14579.538, a 7-contact hand: size 1-2 and about 2,000 units of
     * travel).  Every later held frame shows as route=18 on its WHY line.
     */
    if (v0127HoldToLog != 0) {
        LONG v0127Size;
        LONG64 v0127SizeTime;
        LONG64 v0127LogNow;

        v0127SizeTime = InterlockedCompareExchange64(&g_A486Time100ns, 0, 0);
        v0127Size = InterlockedCompareExchange(&g_A486MaxSize, 0, 0);
        v0127LogNow = (LONG64)KeQueryInterruptTime();

        DbgPrintEx(
            DPFLTR_IHVDRIVER_ID, DPFLTR_ERROR_LEVEL,
            "PalmRejFilter V0127: PALM-ID-HOLD episode=%ld dev=%ld branch=%s "
            "wireIds=0x%03lX markAgeUs=%I64d classUs=%I64d active=%ld "
            "reported=%ld size=%ld sizeAgeUs=%I64d moveMax=%ld "
            "penAgeUs=%I64d marks=%I64d holds=%I64d action=HOLD-UNTIL-LIFT\n",
            snapshotEpisodeId,
            DeviceId,
            PalmV0117BranchName(v0127Route),
            v0127Ids,
            v0127MarkAgeUs,
            v0127ClassUs,
            activeSlotCount,
            v28alReportedCount,
            v0127Size,
            (v0127SizeTime > 0 && v0127LogNow >= v0127SizeTime)
                ? ((v0127LogNow - v0127SizeTime) / 10)
                : -1LL,
            v0127MoveMax,
            penAgeUs,
            InterlockedCompareExchange64(&g_V0127Marks, 0, 0),
            InterlockedIncrement64(&g_V0127Holds));
    }

